package com.kotoba.window;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.provider.Settings;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
public class MainActivity extends Activity {
 Store store;StudyView study;boolean ready=false,foreground=false;final int EXPORT=10,IMPORT=11;
 public void onCreate(Bundle b){super.onCreate(b);TextView loading=new TextView(this);loading.setText("小词窗\n正在载入离线词库…");loading.setGravity(Gravity.CENTER);setContentView(loading);new Thread(()->{try{Store loaded=Store.get(this);runOnUiThread(()->{store=loaded;ready=true;build();});}catch(Throwable e){runOnUiThread(()->loading.setText("载入失败："+e.getMessage()));}}).start();}
 void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xff171b25);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});LinearLayout header=new LinearLayout(this);study=new StudyView(this,false);study.active=foreground;study.ink=0xffedf1ff;header.addView(study.text("あ  小词窗",20,0xffedf1ff),new LinearLayout.LayoutParams(0,-2,1));Button floatBtn=study.button("悬浮",()->overlay(),false);header.addView(floatBtn);root.addView(header);LinearLayout nav=new LinearLayout(this);study.addButton(nav,study.button("背单词",()->study.next(),false));study.addButton(nav,study.button("词库",()->library(),false));study.addButton(nav,study.button("设置",()->settings(),false));root.addView(nav);root.addView(study,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.requestApplyInsets();}
 @Override protected void onResume(){super.onResume();foreground=true;stopService(new Intent(this,OverlayService.class));if(ready)build();}
 @Override protected void onPause(){super.onPause();foreground=false;if(study!=null){study.active=false;if(study.pendingSpeech!=null)study.removeCallbacks(study.pendingSpeech);}Voice.get(this).stop();}
 void overlay(){if(!Settings.canDrawOverlays(this)){new AlertDialog.Builder(this).setTitle("允许悬浮卡片").setMessage("请在系统页面允许小词窗显示在其他应用上层，再返回点击悬浮。").setPositiveButton("去授权",(d,w)->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())))).setNegativeButton("取消",null).show();return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},22);startForegroundService(new Intent(this,OverlayService.class));moveTaskToBack(true);}
 void settings(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(24,12,24,12);ScrollView sc=new ScrollView(this);sc.addView(box);Button levels=new Button(this);levels.setText("选择词库（可多选）");levels.setOnClickListener(v->levels());box.addView(levels);
 setting(box,"自动发音","AutoSpeak",true);setting(box,"新词乱序","Shuffle",false);setting(box,"翻面前显示假名","ShowReading",true);setting(box,"悬浮窗透明背景","Transparent",false);
 CheckBox dark=new CheckBox(this);dark.setText("暗色主题");dark.setChecked(!"Light".equals(store.settings().optString("Theme")));dark.setOnCheckedChangeListener((b,c)->{Store.put(store.settings(),"Theme",c?"Dark":"Light");saveSettings();});box.addView(dark);
 TextView label=new TextView(this);label.setText("每日新词额度（所有等级共享）");box.addView(label);EditText daily=new EditText(this);daily.setInputType(2);daily.setText(""+store.settings().optInt("DailyNew",20));box.addView(daily);
 TextView opacityLabel=new TextView(this);opacityLabel.setText("悬浮背景浓度");box.addView(opacityLabel);SeekBar opacity=new SeekBar(this);opacity.setMax(80);opacity.setProgress((int)(store.settings().optDouble("BackgroundOpacity",.8)*100)-20);box.addView(opacity);
 Button reshuffle=new Button(this);reshuffle.setText("重新洗牌");reshuffle.setOnClickListener(v->{Store.put(store.settings(),"ShuffleSeed",new Random().nextInt());Store.put(store.settings(),"Shuffle",true);saveSettings();Toast.makeText(this,"已重新洗牌",0).show();});box.addView(reshuffle);
 for(String name:new String[]{"导出进度","导入进度","来源与许可"}){Button b=new Button(this);b.setText(name);box.addView(b);b.setOnClickListener(v->{if(name.equals("来源与许可"))licenses();else if(name.equals("导出进度")){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"小词窗进度.json");startActivityForResult(i,EXPORT);}else{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}});}
 TextView info=new TextView(this);info.setText("安卓 1.0.0 · N5–N1 共 "+store.words.size()+" 词\nSupertonic 3 离线神经语音 · 无需网络\n首次发音会初始化模型，之后使用缓存。\n悬浮条可拖动、收起，通知栏可返回主界面。\nOPPO 如自动关闭悬浮窗，请在应用电池设置允许后台运行。\n可导入 Windows 小词窗导出的 JSON 进度。");info.setPadding(0,24,0,0);box.addView(info);
 new AlertDialog.Builder(this).setTitle("学习设置").setView(sc).setPositiveButton("保存",(d,w)->{try{int n=Integer.parseInt(daily.getText().toString());if(n<0||n>1000)throw new Exception();Store.put(store.settings(),"DailyNew",n);Store.put(store.settings(),"BackgroundOpacity",(opacity.getProgress()+20)/100d);saveSettings();study.next();}catch(Exception e){Toast.makeText(this,"新词额度请输入 0–1000",1).show();}}).setNegativeButton("关闭",(d,w)->study.next()).show();}
 void saveSettings(){study.undo=null;if(!store.save())Toast.makeText(this,store.warning,1).show();study.render();}
 void setting(LinearLayout box,String label,String key,boolean def){CheckBox b=new CheckBox(this);b.setText(label);b.setChecked(store.settings().optBoolean(key,def));b.setOnCheckedChangeListener((v,c)->{Store.put(store.settings(),key,c);if(key.equals("AutoSpeak")&&!c)Voice.get(this).stop();saveSettings();});box.addView(b);}
 void levels(){boolean[] chosen=new boolean[5];for(int i=0;i<5;i++)chosen[i]=store.includes(5-i);new AlertDialog.Builder(this).setTitle("词库等级").setMultiChoiceItems(new String[]{"N5","N4","N3","N2","N1"},chosen,(d,i,c)->chosen[i]=c).setPositiveButton("应用",(d,w)->{JSONArray a=new JSONArray();for(int i=0;i<5;i++)if(chosen[i])a.put(5-i);if(a.length()==0){Toast.makeText(this,"请至少选择一个等级",0).show();return;}Store.put(store.settings(),"Levels",a);Store.put(store.settings(),"Level",a.optInt(0));saveSettings();study.next();}).setNegativeButton("取消",null).show();}
 void library(){LinearLayout box=new LinearLayout(this);box.setOrientation(1);EditText query=new EditText(this);query.setHint("搜索日语、假名或中文");box.addView(query);CheckBox stars=new CheckBox(this);stars.setText("只看收藏");box.addView(stars);ListView list=new ListView(this);box.addView(list,new LinearLayout.LayoutParams(-1,study.dp(360)));ArrayList<JSONObject> found=new ArrayList<>();Runnable refresh=()->{found.clear();String q=query.getText().toString().trim();ArrayList<String> titles=new ArrayList<>();for(JSONObject w:store.words){JSONObject r=store.progress(w);if(!store.includes(w.optInt("Level"))||(stars.isChecked()&&(r==null||!r.optBoolean("Star"))))continue;if((w.optString("Term")+w.optString("Reading")+w.optString("Meaning")).contains(q)){found.add(w);titles.add(w.optString("Term")+"  "+w.optString("Reading")+"  N"+w.optInt("Level")+"\n"+w.optString("Meaning"));if(found.size()==200)break;}}list.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,titles));};query.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){refresh.run();}public void afterTextChanged(android.text.Editable e){}});stars.setOnCheckedChangeListener((b,c)->refresh.run());AlertDialog dialog=new AlertDialog.Builder(this).setTitle("所选等级 · 最多显示 200 条").setView(box).setNegativeButton("关闭",null).create();list.setOnItemClickListener((a,v,i,id)->{study.showWord(found.get(i));dialog.dismiss();});refresh.run();dialog.show();}
 void licenses(){try{new AlertDialog.Builder(this).setTitle("来源与许可").setMessage(Store.read(getAssets().open("VOCAB_SOURCE.md"))+"\n应用代码 MIT；Supertonic 模型 OpenRAIL-M；sherpa-onnx Apache-2.0；ONNX Runtime MIT。完整许可已随 APK 附带。").setPositiveButton("确定",null).show();}catch(Exception e){}}
 @Override protected void onActivityResult(int req,int result,Intent intent){super.onActivityResult(req,result,intent);if(result!=RESULT_OK||intent==null||intent.getData()==null)return;try{if(req==EXPORT){try(OutputStream o=getContentResolver().openOutputStream(intent.getData())){o.write(store.data.toString().getBytes("UTF-8"));}Toast.makeText(this,"进度已导出",0).show();}else if(req==IMPORT){JSONObject candidate=new JSONObject(Store.read(getContentResolver().openInputStream(intent.getData())));Store.validate(candidate);new AlertDialog.Builder(this).setTitle("替换当前学习进度？").setMessage("建议先导出原进度。导入支持小词窗 Windows／Android JSON 格式。").setPositiveButton("导入",(d,w)->{JSONObject old=store.data;store.data=candidate;if(store.save()){study.undo=null;study.next();}else{store.data=old;Toast.makeText(this,store.warning,1).show();}}).setNegativeButton("取消",null).show();}}catch(Exception e){Toast.makeText(this,"操作失败："+e.getMessage(),1).show();}}
}